import * as S from './state.mjs';
import {ensureCalendar,addDays,dayNumber,monthDays,eventsOn,validateTargetDate} from './calendar-core.mjs';
import {beginCalendarHoliday,nextCalendarAction,prepareCalendarGame,advanceCalendarDay} from './calendar-operations.mjs';
import {officeCounts,syncOffice} from './newsroom.mjs';
import {assertCanAdvance} from './compliance.mjs';
import {icon} from './presentation.mjs';
const arg=v=>esc(JSON.stringify(v));
const label=(date,opts={})=>new Date(dayNumber(date)*86400000).toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric',...opts});
export function installCalendarUI({views,initialize,isBusy,setBusy,settleRound}){
 let month=ensureCalendar(state).date.slice(0,7),selected=ensureCalendar(state).date,target=addDays(ensureCalendar(state).date,7),stopping=false;
 const previous=ensureCalendar(state).session;if(previous?.status==='running'){previous.status='paused';previous.message='The holiday is ready to resume.';}
 function mutate(fn){state=S.transact(state,fn);save();}
 function view(){const c=ensureCalendar(state),session=c.session,days=monthDays(month),events=eventsOn(state,selected),future=selected>c.date,busy=isBusy();return `<div class="calendar-workspace"><section class="calendar-hero"><div><span class="eyebrow">YOUR FOOTBALL YEAR</span><h2>${label(c.date,{weekday:'long',year:'numeric'})}</h2><p>${esc(clubs[state.team][1]+' '+clubs[state.team][2])} · ${state.phase==='offseason'?'Offseason':state.phase==='playoffs'?'Postseason':'Regular season'}</p></div><div class="calendar-deputy">${icon('calendar')}<span><small>NEXT MATCHDAY</small><b>${c.nextRoundDate&&state.phase!=='offseason'?label(c.nextRoundDate,{weekday:'short'}):'Offseason'}</b><small>The calendar stops whenever a decision needs you.</small></span></div></section>${session?.status==='running'?`<div class="calendar-progress" role="status"><span><b>Simulating to ${label(session.target,{year:'numeric'})}</b><small>${label(c.date)} · ${session.rounds} rounds completed</small></span><button class="secondary small" onclick="Calendar.stop()">${stopping?'Stopping…':'Stop simulation'}</button></div>`:session?.status==='paused'?`<div class="calendar-paused"><span><b>Holiday paused</b><small>${esc(session.message)} · Target ${label(session.target)}</small></span><button class="small" onclick="Calendar.resume()" ${busy?'disabled':''}>Resume →</button></div>`:''}<div class="calendar-layout"><section class="calendar-month"><div class="calendar-month-head"><div><button aria-label="Previous month" onclick="Calendar.month(-1)">‹</button><h3>${label(month+'-01',{month:'long',year:'numeric',day:undefined})}</h3><button aria-label="Next month" onclick="Calendar.month(1)">›</button></div><button class="secondary small" onclick="Calendar.today()">Today</button></div><div class="calendar-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${days.map(date=>{const e=eventsOn(state,date),game=e.find(e=>e.game),isToday=date===c.date;return `<button class="calendar-day ${date.slice(0,7)!==month?'outside':''} ${isToday?'today':''} ${date===selected?'selected':''} ${e.length?'has-event':''}" onclick="Calendar.pick('${date}')" aria-label="${label(date,{weekday:'long',year:'numeric'})}${e.length?', '+e.map(x=>x.kind).join(', '):''}" aria-pressed="${date===selected}"><span>${Number(date.slice(-2))}</span>${game?`<img src="${logoSource(game.game.a===state.team?game.game.b:game.game.a)}" alt="${esc(clubs[game.game.a===state.team?game.game.b:game.game.a][2])}"><small>${game.game.score?game.game.score.join('–'):'MATCHDAY'}</small>`:e.length?`<i></i><small>${esc(e[0].kind)}</small>`:''}</button>`;}).join('')}</div><div class="calendar-legend"><span><i></i> Fixture / league event</span><span>● Today</span><button class="link" onclick="W.open('Schedule')">Full fixture list →</button></div></section><div class="calendar-side"><section><span class="eyebrow">${label(selected,{weekday:'long'})}</span><h3>${label(selected,{month:'long',year:'numeric'})}</h3>${events.map(e=>`<div class="calendar-event"><b>${esc(e.kind)}</b>${e.game?`<span>${esc(clubs[e.game.a][2])} vs ${esc(clubs[e.game.b][2])}</span>`:''}<small>${e.game?.score?e.game.score.join(' – '):e.status}</small></div>`).join('')||'<p>Preparation, recovery and club correspondence.</p>'}${future?`<button class="small" onclick="Calendar.start('${selected}')" ${busy?'disabled':''}>Simulate to this date →</button>`:''}</section><section><span class="eyebrow">GO ON HOLIDAY</span><h3>Choose your return date.</h3><label class="calendar-date-label">Simulation target<input aria-label="Simulation target date" type="date" min="${addDays(c.date,1)}" max="${addDays(c.date,730)}" value="${target}" onchange="Calendar.target(this.value)" ${busy?'disabled':''}></label><p>The calendar pauses for inbox decisions, interviews and roster problems so you can handle them yourself.</p><button onclick="Calendar.start()" ${busy?'disabled':''}>Simulate to date →</button><div class="calendar-shortcuts"><button class="secondary small" onclick="Calendar.start('${addDays(c.date,1)}')" ${busy?'disabled':''}>1 day</button><button class="secondary small" onclick="Calendar.start('${addDays(c.date,7)}')" ${busy?'disabled':''}>1 week</button><button class="secondary small" onclick="Calendar.start('${addDays(c.date,28)}')" ${busy?'disabled':''}>4 weeks</button></div></section></div></div></div>`;}
 function logoSource(team){const html=logo(team),match=html.match(/src=["']([^"']+)/);return match?.[1]||'';}
 async function start(date=target){if(isBusy()||animating){toast('Finish the current play before starting a holiday.');return;}try{initialize();mutate(s=>beginCalendarHoliday(s,date));}catch(e){toast(e.message);return;}pauseAuto();window.broadcast?.stop();setBusy(true);stopping=false;W.open('Calendar');render();let completed=false;
 try{for(let safety=0;safety<1000&&!stopping;safety++){const action=nextCalendarAction(state,date),session=ensureCalendar(state).session;if(action.kind==='done'){completed=true;break;}syncOffice(state);if(officeCounts(state).urgent||state.interviewPending||state.franchise.cinema?.active)throw Error('An urgent club matter or interview is waiting in your inbox.');
 const before=structuredClone(state);try{if(action.kind==='game'){mutate(s=>prepareCalendarGame(s,action.date));assertCanAdvance(state,{game:true});await settleRound({live:state.live});mutate(s=>{ensureCalendar(s).session.rounds++;});}else mutate(s=>advanceCalendarDay(s,action.date));}catch(e){state=before;throw e;}
 if(safety%7===0||action.kind==='game'){render();await new Promise(resolve=>setTimeout(resolve,0));}}
 mutate(s=>{const c=ensureCalendar(s);c.session.status=completed?'complete':'paused';c.session.message=completed?'Your selected return date has arrived.':'Stopped at your request.';});
 }catch(e){mutate(s=>{const c=ensureCalendar(s);c.session.status='paused';c.session.message=e.message;});toast(e.message);}finally{setBusy(false);month=ensureCalendar(state).date.slice(0,7);selected=ensureCalendar(state).date;target=addDays(selected,7);save();render();}}
 window.Calendar={start,stop(){stopping=true;render();},resume(){const s=ensureCalendar(state).session;if(s)start(s.target);},target(v){target=v;},pick(v){selected=v;render();},today(){selected=ensureCalendar(state).date;month=selected.slice(0,7);render();},month(delta){const d=new Date(month+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);month=d.toISOString().slice(0,7);render();}};
 views.Calendar=view;
 F.holiday=(rounds=1)=>{const c=ensureCalendar(state),days=Math.min(700,Math.max(0,Number(rounds)-1)*7),returnDate=addDays(c.nextRoundDate||c.date,days);return start(returnDate);};F.stopHoliday=Calendar.stop;
}
